/**
 * @fileoverview Verification-only AST linter enforcing 100% substantive TSDoc coverage
 * across all Angular TypeScript source files in `pulse-query-ng-web/src`.
 *
 * Uses the official TypeScript compiler AST API (`typescript`) to reject missing JSDoc
 * comments as well as lazy placeholder stubs (`@docs`, `doc`, `Autogenerated doc`,
 * `<name> property.`, `<Name> component.`, `Store.`, `Creates a new <Name>.`, `Ng On Init.`).
 */

import * as fs from "fs";
import * as path from "path";
import * as ts from "typescript";

/**
 * Regular expressions matching forbidden placeholder or auto-generated stub JSDoc comments.
 */
export const BANNED_PATTERNS: readonly RegExp[] = [
  /\bAutogenerated doc\b/i,
  /^@docs$/i,
  /^doc$/i,
  /\/\*\*\s*@docs\s*\*\//i,
  /\/\*\*\s*doc\s*\*\//i,
  /^[A-Za-z0-9_$]+\s+property\.$/i,
  /^(?:[A-Za-z0-9_]+\s+){1,2}(?:component|service|store|pipe|directive|guard|dialog)\.$/i,
  /^(Store|Dialog|Router)\.$/i,
  /^Creates a new [A-Za-z0-9_]+\.$/i,
  /^Ng On (Init|Destroy|Changes)\.$/i,
  /^Initialize component\.$/i,
];

/**
 * Checks whether a raw JSDoc comment or description contains banned placeholder text.
 *
 * @param text - The JSDoc comment text to inspect.
 * @returns True if the text is empty or matches a banned placeholder pattern.
 */
export function isPlaceholderDoc(text: string): boolean {
  const trimmed = text.trim();
  if (!trimmed) {
    return true;
  }
  return BANNED_PATTERNS.some((pattern) => pattern.test(trimmed));
}

/**
 * Recursively collects all `.ts` application source files under `dirPath`,
 * excluding `.spec.ts` files, `api-client`, and test utilities.
 *
 * @param dirPath - Root directory to scan.
 * @param acc - Mutable accumulator of discovered file paths.
 * @returns Array of matching TypeScript file paths.
 */
export function collectSourceFiles(
  dirPath: string,
  acc: string[] = [],
): string[] {
  const entries = fs.readdirSync(dirPath, { withFileTypes: true });
  for (const entry of entries) {
    const fullPath = path.join(dirPath, entry.name);
    if (entry.isDirectory()) {
      if (entry.name === "api-client" || entry.name === "test-utils") {
        continue;
      }
      collectSourceFiles(fullPath, acc);
    } else if (
      entry.isFile() &&
      entry.name.endsWith(".ts") &&
      !entry.name.endsWith(".spec.ts") &&
      !entry.name.endsWith(".d.ts") &&
      entry.name !== "test-setup.ts"
    ) {
      acc.push(fullPath);
    }
  }
  return acc;
}

/**
 * Extracts JSDoc nodes attached to a TypeScript AST node.
 *
 * @param node - TypeScript AST node to inspect.
 * @returns Array of `ts.JSDoc` nodes attached to `node`.
 */
function getJsDocNodes(node: ts.Node): readonly ts.JSDoc[] {
  const raw = (node as { jsDoc?: readonly ts.JSDoc[] }).jsDoc;
  return raw ?? [];
}

/**
 * Converts a `ts.JSDoc` comment field into a plain string.
 *
 * @param comment - JSDoc comment string or node array.
 * @returns Flattened comment text.
 */
export function flattenJsDocComment(
  comment: string | ts.NodeArray<ts.JSDocComment> | undefined,
): string {
  if (!comment) {
    return "";
  }
  if (typeof comment === "string") {
    return comment.trim();
  }
  return comment
    .map((part) => part.text)
    .join("")
    .trim();
}

/**
 * Validates that an AST node has at least one non-placeholder JSDoc block.
 *
 * @param sf - Parsed TypeScript `SourceFile`.
 * @param node - AST node requiring TSDoc documentation.
 * @param label - Human-readable identifier for diagnostic reporting.
 * @param filePath - Relative file path containing the node.
 * @param errors - Mutable array accumulating validation errors.
 */
export function verifyNodeDoc(
  sf: ts.SourceFile,
  node: ts.Node,
  label: string,
  filePath: string,
  errors: string[],
): void {
  const docs = getJsDocNodes(node);
  const line = sf.getLineAndCharacterOfPosition(node.getStart(sf)).line + 1;
  if (docs.length === 0) {
    errors.push(`${filePath}:${line} - Missing TSDoc on ${label}`);
    return;
  }

  for (const doc of docs) {
    const comment = flattenJsDocComment(doc.comment);
    const fullText = doc.getText(sf).trim();
    const hasTags = Boolean(doc.tags && doc.tags.length > 0);
    if (isPlaceholderDoc(comment) && !hasTags) {
      errors.push(
        `${filePath}:${line} - Empty or placeholder TSDoc description on ${label}: "${comment}"`,
      );
    } else if (
      BANNED_PATTERNS.some((p) => p.test(comment) || p.test(fullText))
    ) {
      errors.push(
        `${filePath}:${line} - Placeholder TSDoc forbidden on ${label}: "${comment}"`,
      );
    }
  }
}

/**
 * Validates that every parameter on a callable node is documented with a non-placeholder `@param` tag.
 *
 * @param sf - Parsed TypeScript `SourceFile`.
 * @param node - Callable AST node with JSDoc annotations.
 * @param params - Parameter declarations belonging to the callable.
 * @param label - Human-readable callable label.
 * @param filePath - Relative file path containing the callable.
 * @param errors - Mutable array accumulating validation errors.
 */
export function verifyParameterDocs(
  sf: ts.SourceFile,
  node: ts.Node,
  params: readonly ts.ParameterDeclaration[],
  label: string,
  filePath: string,
  errors: string[],
): void {
  if (params.length === 0) {
    return;
  }
  const docs = getJsDocNodes(node);
  if (docs.length === 0) {
    return;
  }

  const paramTags = new Map<string, string>();
  for (const doc of docs) {
    for (const tag of doc.tags ?? []) {
      if (ts.isJSDocParameterTag(tag)) {
        const paramName = tag.name.getText(sf).trim();
        const commentText = flattenJsDocComment(tag.comment)
          .replace(/^-\s*/, "")
          .trim();
        paramTags.set(paramName, commentText);
      }
    }
  }

  for (const param of params) {
    const pName = param.name.getText(sf).trim();
    const line = sf.getLineAndCharacterOfPosition(param.getStart(sf)).line + 1;
    if (!paramTags.has(pName)) {
      errors.push(
        `${filePath}:${line} - Missing @param ${pName} TSDoc on ${label}`,
      );
    } else if (isPlaceholderDoc(paramTags.get(pName) ?? "")) {
      errors.push(
        `${filePath}:${line} - Placeholder or empty @param ${pName} description on ${label}`,
      );
    }
  }
}

/**
 * Verifies a single TypeScript source file's content and returns all TSDoc errors found.
 *
 * @param fullText - Raw TypeScript file content.
 * @param relPath - Relative file path for error reporting.
 * @returns Array of diagnostic error strings.
 */
export function verifySourceFileText(
  fullText: string,
  relPath: string,
): string[] {
  const errors: string[] = [];
  const sf = ts.createSourceFile(
    relPath,
    fullText,
    ts.ScriptTarget.Latest,
    true,
  );

  if (!fullText.includes("@fileoverview")) {
    errors.push(`${relPath}:1 - Missing @fileoverview header comment`);
  }
  if (
    /\/\*\*\s*(@docs|doc)\s*\*\//i.test(fullText) ||
    /\bAutogenerated doc\b/i.test(fullText)
  ) {
    errors.push(
      `${relPath}:1 - File contains banned placeholder doc comment (@docs / doc)`,
    );
  }

  ts.forEachChild(sf, (node) => {
    if (ts.isClassDeclaration(node)) {
      const clsName = node.name ? node.name.getText(sf) : "<anonymous class>";
      verifyNodeDoc(sf, node, `class ${clsName}`, relPath, errors);
      for (const member of node.members) {
        if (ts.isPropertyDeclaration(member)) {
          const propName = member.name.getText(sf);
          verifyNodeDoc(
            sf,
            member,
            `property ${clsName}.${propName}`,
            relPath,
            errors,
          );
        } else if (ts.isConstructorDeclaration(member)) {
          verifyNodeDoc(sf, member, `constructor ${clsName}`, relPath, errors);
          verifyParameterDocs(
            sf,
            member,
            member.parameters,
            `constructor ${clsName}`,
            relPath,
            errors,
          );
        } else if (ts.isMethodDeclaration(member)) {
          const mLabel = `method ${clsName}.${member.name.getText(sf)}`;
          verifyNodeDoc(sf, member, mLabel, relPath, errors);
          verifyParameterDocs(
            sf,
            member,
            member.parameters,
            mLabel,
            relPath,
            errors,
          );
        } else if (ts.isGetAccessorDeclaration(member)) {
          verifyNodeDoc(
            sf,
            member,
            `getter ${clsName}.${member.name.getText(sf)}`,
            relPath,
            errors,
          );
        } else if (ts.isSetAccessorDeclaration(member)) {
          verifyNodeDoc(
            sf,
            member,
            `setter ${clsName}.${member.name.getText(sf)}`,
            relPath,
            errors,
          );
        }
      }
    } else if (ts.isInterfaceDeclaration(node)) {
      const intfName = node.name.getText(sf);
      verifyNodeDoc(sf, node, `interface ${intfName}`, relPath, errors);
      for (const member of node.members) {
        if (ts.isPropertySignature(member) && member.name) {
          verifyNodeDoc(
            sf,
            member,
            `interface property ${intfName}.${member.name.getText(sf)}`,
            relPath,
            errors,
          );
        } else if (ts.isMethodSignature(member) && member.name) {
          verifyNodeDoc(
            sf,
            member,
            `interface method ${intfName}.${member.name.getText(sf)}`,
            relPath,
            errors,
          );
        }
      }
    } else if (ts.isTypeAliasDeclaration(node)) {
      verifyNodeDoc(sf, node, `type ${node.name.getText(sf)}`, relPath, errors);
    } else if (ts.isFunctionDeclaration(node)) {
      const fnName = node.name ? node.name.getText(sf) : "<anonymous function>";
      verifyNodeDoc(sf, node, `function ${fnName}`, relPath, errors);
      verifyParameterDocs(
        sf,
        node,
        node.parameters,
        `function ${fnName}`,
        relPath,
        errors,
      );
    } else if (ts.isEnumDeclaration(node)) {
      const enumName = node.name.getText(sf);
      verifyNodeDoc(sf, node, `enum ${enumName}`, relPath, errors);
      for (const member of node.members) {
        verifyNodeDoc(
          sf,
          member,
          `enum member ${enumName}.${member.name.getText(sf)}`,
          relPath,
          errors,
        );
      }
    }
  });

  return errors;
}

/**
 * Runs the AST documentation verifier across the Angular frontend project.
 *
 * @param customSrcDir - Optional directory override for testing.
 * @returns Process exit code (`0` when all files pass, `1` when violations exist).
 */
export function verifyFrontendDocs(customSrcDir?: string): number {
  const rootDir = path.resolve(__dirname, "..");
  const srcDir =
    customSrcDir ?? path.join(rootDir, "pulse-query-ng-web", "src");
  const sourceFiles = collectSourceFiles(srcDir);

  const errors: string[] = [];
  for (const filePath of sourceFiles) {
    const relPath = path.relative(rootDir, filePath);
    const fullText = fs.readFileSync(filePath, "utf8");
    errors.push(...verifySourceFileText(fullText, relPath));
  }

  if (errors.length > 0) {
    console.error(`TSDoc verification failed with ${errors.length} error(s):`);
    for (const err of errors) {
      console.error(`  - ${err}`);
    }
    return 1;
  }

  console.log(
    `Verified ${sourceFiles.length} TypeScript source files with 100% TSDoc coverage.`,
  );
  return 0;
}

if (require.main === module) {
  process.exit(verifyFrontendDocs());
}
